<?php

declare(strict_types=1);

/**
 * Prints the CREATE TABLE / index / foreign-key SQL of every DB entity of the reference application (the framework's,
 * `ddd-ai`'s and the package's), generated by the framework from the entity attributes
 * (`EntityModelGeneratorService::getDatabaseModels()`, the generator behind `app:entity:show-sql`) — with each table
 * named as its COMMITTED Doctrine model names it. Where a committed model names its table differently from the
 * generator (a generator run with a table prefix, e.g. `AIConversationCompactionNodes` generated with the host's
 * prefix), the renames are listed as SQL comments at the top. Executes nothing.
 *
 *   php examples/reference-kernel/bin/print-schema-sql.php > schema.sql
 */

use AgentsReference\ReferenceKernel;
use DDD\Domain\Common\Services\EntityModelGeneratorService;

ini_set('memory_limit', '1G');
require dirname(__DIR__) . '/bootstrap.php';
$kernel = new ReferenceKernel((string)($_SERVER['APP_ENV'] ?? 'prod'), false);
$kernel->boot();

$databaseModels = EntityModelGeneratorService::filterOutExcludedTables(
    EntityModelGeneratorService::getDatabaseModels(null, filterOverriddenEntities: true)
);
$schemaSql = $databaseModels->getSql();
$committedTableNamesByGeneratedName = [];
foreach ($databaseModels->getElements() as $databaseModel) {
    $modelClassName = $databaseModel->modelClassWithNamespace?->getNameWithNamespace();
    if ($modelClassName === null || !class_exists($modelClassName) || !defined($modelClassName . '::TABLE_NAME')) {
        continue;
    }
    $committedTableName = (string)constant($modelClassName . '::TABLE_NAME');
    if ($committedTableName !== '' && $committedTableName !== $databaseModel->sqlTableName) {
        $committedTableNamesByGeneratedName[(string)$databaseModel->sqlTableName] = $committedTableName;
    }
}
foreach ($committedTableNamesByGeneratedName as $generatedTableName => $committedTableName) {
    echo "-- table renamed to its committed model's name: {$generatedTableName} -> {$committedTableName}\n";
    $schemaSql = str_replace('`' . $generatedTableName . '`', '`' . $committedTableName . '`', $schemaSql);
}
// the generator emits tables in entity order, so a foreign key may name a table created further down
echo "SET FOREIGN_KEY_CHECKS=0;\n" . $schemaSql . "\nSET FOREIGN_KEY_CHECKS=1;\n";
